    "CREATE TABLE `faculty_allocations` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `faculty_id` int(11) NOT NULL,\n  `subject_id` int(11) NOT NULL,\n  `class_id` int(11) DEFAULT NULL,\n  `division_id` int(11) DEFAULT NULL,\n  `semester_id` int(11) DEFAULT NULL,\n  `course_batch_id` int(11) DEFAULT NULL,\n  `allocated_hours` decimal(4,1) DEFAULT 0.0,\n  `workload_percentage` decimal(5,2) DEFAULT 100.00,\n  `is_primary` tinyint(1) DEFAULT 1,\n  `allocation_type` enum('Regular','Guest','Visiting','Part-time') DEFAULT 'Regular',\n  `start_date` date DEFAULT NULL,\n  `end_date` date DEFAULT NULL,\n  `notes` text DEFAULT NULL,\n  `created_at` timestamp NULL DEFAULT current_timestamp(),\n  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\n  PRIMARY KEY (`id`),\n  KEY `class_id` (`class_id`),\n  KEY `division_id` (`division_id`),\n  KEY `course_batch_id` (`course_batch_id`),\n  KEY `idx_allocation_faculty` (`faculty_id`),\n  KEY `idx_allocation_subject` (`subject_id`),\n  KEY `idx_allocation_semester` (`semester_id`),\n  KEY `idx_allocation_primary` (`is_primary`),\n  CONSTRAINT `faculty_allocations_ibfk_2` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`) ON DELETE CASCADE,\n  CONSTRAINT `faculty_allocations_ibfk_3` FOREIGN KEY (`class_id`) REFERENCES `classes` (`id`) ON DELETE SET NULL,\n  CONSTRAINT `faculty_allocations_ibfk_4` FOREIGN KEY (`division_id`) REFERENCES `divisions` (`id`) ON DELETE SET NULL,\n  CONSTRAINT `faculty_allocations_ibfk_5` FOREIGN KEY (`semester_id`) REFERENCES `semesters` (`id`) ON DELETE SET NULL,\n  CONSTRAINT `faculty_allocations_ibfk_6` FOREIGN KEY (`course_batch_id`) REFERENCES `course_batches` (`id`) ON DELETE SET NULL,\n  CONSTRAINT `fk_faculty_allocations_faculty_id` FOREIGN KEY (`faculty_id`) REFERENCES `faculty` (`user_id`) ON DELETE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Faculty subject allocations with workload tracking'",
    "CREATE TABLE `faculty_availability` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `faculty_id` int(11) NOT NULL,\n  `day_of_week` tinyint(4) NOT NULL COMMENT '1=Monday, 7=Sunday',\n  `is_available` tinyint(1) DEFAULT 1,\n  `shift_pattern_id` int(11) DEFAULT NULL,\n  `start_time` time DEFAULT NULL,\n  `end_time` time DEFAULT NULL,\n  `notes` text DEFAULT NULL,\n  `created_at` timestamp NULL DEFAULT current_timestamp(),\n  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\n  PRIMARY KEY (`id`),\n  KEY `idx_faculty` (`faculty_id`),\n  KEY `idx_day` (`day_of_week`),\n  KEY `idx_available` (`is_available`),\n  KEY `fk_faculty_avail_shift` (`shift_pattern_id`),\n  KEY `idx_faculty_day` (`faculty_id`,`day_of_week`),\n  KEY `idx_availability_time` (`faculty_id`,`day_of_week`,`start_time`,`end_time`),\n  CONSTRAINT `fk_faculty_avail_faculty` FOREIGN KEY (`faculty_id`) REFERENCES `faculty` (`user_id`) ON DELETE CASCADE,\n  CONSTRAINT `fk_faculty_avail_shift` FOREIGN KEY (`shift_pattern_id`) REFERENCES `shift_patterns` (`id`) ON DELETE SET NULL\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Faculty weekly availability with shift templates and custom time slots. start_time/end_time can differ from shift times.'",
    "CREATE TABLE `proxy_assignments` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `original_faculty_id` int(11) NOT NULL,\n  `proxy_faculty_id` int(11) NOT NULL,\n  `subject_id` int(11) NOT NULL,\n  `course_id` int(11) NOT NULL,\n  `class_id` int(11) DEFAULT NULL,\n  `division_id` int(11) DEFAULT NULL,\n  `day_of_week` varchar(20) DEFAULT NULL,\n  `start_time` time DEFAULT NULL,\n  `end_time` time DEFAULT NULL,\n  `assignment_date` date NOT NULL,\n  `reason` enum('absence','workload','expertise','manual') DEFAULT 'absence',\n  `status` enum('pending','confirmed','rejected','completed') DEFAULT 'pending',\n  `created_at` datetime DEFAULT current_timestamp(),\n  `created_by` int(11) DEFAULT NULL,\n  PRIMARY KEY (`id`),\n  KEY `idx_original_faculty` (`original_faculty_id`),\n  KEY `idx_proxy_faculty` (`proxy_faculty_id`),\n  KEY `idx_date` (`assignment_date`),\n  KEY `subject_id` (`subject_id`),\n  CONSTRAINT `proxy_assignments_ibfk_1` FOREIGN KEY (`original_faculty_id`) REFERENCES `faculty` (`user_id`),\n  CONSTRAINT `proxy_assignments_ibfk_2` FOREIGN KEY (`proxy_faculty_id`) REFERENCES `faculty` (`user_id`),\n  CONSTRAINT `proxy_assignments_ibfk_3` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
    "CREATE TABLE `shift_change_requests` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `faculty_id` int(11) NOT NULL,\n  `day_of_week` tinyint(4) NOT NULL COMMENT '1=Monday, 7=Sunday',\n  `current_shift_name` varchar(100) DEFAULT NULL,\n  `requested_shift_name` varchar(100) NOT NULL,\n  `reason` text DEFAULT NULL,\n  `status` enum('pending','approved','rejected') DEFAULT 'pending',\n  `admin_response` text DEFAULT NULL,\n  `created_at` timestamp NULL DEFAULT current_timestamp(),\n  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\n  `reviewed_by` int(11) DEFAULT NULL,\n  `reviewed_at` timestamp NULL DEFAULT NULL,\n  PRIMARY KEY (`id`),\n  KEY `idx_faculty` (`faculty_id`),\n  KEY `idx_status` (`status`),\n  KEY `fk_shift_req_reviewer` (`reviewed_by`),\n  CONSTRAINT `fk_shift_req_faculty` FOREIGN KEY (`faculty_id`) REFERENCES `faculty` (`user_id`) ON DELETE CASCADE,\n  CONSTRAINT `fk_shift_req_reviewer` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
    "CREATE TABLE `timetable` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `course_id` int(11) NOT NULL,\n  `class_id` int(11) NOT NULL,\n  `division_id` int(11) DEFAULT NULL,\n  `day_of_week` enum('Monday','Tuesday','Wednesday','Thursday','Friday','Saturday') NOT NULL,\n  `start_time` time NOT NULL,\n  `end_time` time NOT NULL,\n  `subject_id` int(11) NOT NULL,\n  `faculty_id` int(11) NOT NULL,\n  `room_id` int(11) DEFAULT NULL,\n  `academic_year_id` int(11) DEFAULT NULL,\n  `semester_id` int(11) DEFAULT NULL,\n  `course_batch_id` int(11) DEFAULT NULL,\n  `room_number` varchar(20) DEFAULT NULL,\n  `timetable_type` enum('Regular','Exam','Special','Makeup') DEFAULT 'Regular',\n  `is_active` tinyint(1) DEFAULT 1,\n  `created_at` timestamp NULL DEFAULT current_timestamp(),\n  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\n  PRIMARY KEY (`id`),\n  KEY `class_id` (`class_id`),\n  KEY `division_id` (`division_id`),\n  KEY `subject_id` (`subject_id`),\n  KEY `academic_year_id` (`academic_year_id`),\n  KEY `course_batch_id` (`course_batch_id`),\n  KEY `idx_timetable_course_class` (`course_id`,`class_id`),\n  KEY `idx_timetable_day` (`day_of_week`),\n  KEY `idx_timetable_time` (`start_time`,`end_time`),\n  KEY `idx_timetable_faculty` (`faculty_id`),\n  KEY `idx_timetable_room` (`room_id`),\n  KEY `idx_timetable_semester` (`semester_id`),\n  CONSTRAINT `fk_timetable_faculty_id` FOREIGN KEY (`faculty_id`) REFERENCES `faculty` (`user_id`) ON DELETE CASCADE,\n  CONSTRAINT `timetable_ibfk_1` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE CASCADE,\n  CONSTRAINT `timetable_ibfk_2` FOREIGN KEY (`class_id`) REFERENCES `classes` (`id`) ON DELETE CASCADE,\n  CONSTRAINT `timetable_ibfk_3` FOREIGN KEY (`division_id`) REFERENCES `divisions` (`id`) ON DELETE SET NULL,\n  CONSTRAINT `timetable_ibfk_4` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`) ON DELETE CASCADE,\n  CONSTRAINT `timetable_ibfk_6` FOREIGN KEY (`room_id`) REFERENCES `rooms` (`id`) ON DELETE SET NULL,\n  CONSTRAINT `timetable_ibfk_7` FOREIGN KEY (`academic_year_id`) REFERENCES `academic_years` (`id`) ON DELETE SET NULL,\n  CONSTRAINT `timetable_ibfk_8` FOREIGN KEY (`semester_id`) REFERENCES `semesters` (`id`) ON DELETE SET NULL,\n  CONSTRAINT `timetable_ibfk_9` FOREIGN KEY (`course_batch_id`) REFERENCES `course_batches` (`id`) ON DELETE SET NULL,\n  CONSTRAINT `chk_time_slot` CHECK (`end_time` > `start_time`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Timetable schedule'",
    'CREATE TABLE `mobile_request_nonces` (\n  `id` bigint(20) NOT NULL AUTO_INCREMENT,\n  `device_id` varchar(128) NOT NULL,\n  `nonce` varchar(120) NOT NULL,\n  `created_at` timestamp NULL DEFAULT current_timestamp(),\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `uk_mobile_request_nonce` (`device_id`,`nonce`),\n  KEY `idx_mobile_request_nonces_created_at` (`created_at`),\n  KEY `idx_mobile_request_nonces_device_created` (`device_id`,`created_at`),\n  CONSTRAINT `fk_mobile_request_nonces_device_id` FOREIGN KEY (`device_id`) REFERENCES `mobile_devices` (`device_id`) ON DELETE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci',
    'CREATE TABLE `timetable_quality_candidates` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `run_id` varchar(64) NOT NULL,\n  `candidate_index` int(11) NOT NULL,\n  `is_selected` tinyint(1) NOT NULL DEFAULT 0,\n  `quality_score` decimal(5,2) NOT NULL,\n  `clash_risk` decimal(5,4) NOT NULL,\n  `faculty_fatigue` decimal(5,4) NOT NULL,\n  `room_overuse` decimal(5,4) NOT NULL,\n  `student_load_imbalance` decimal(5,4) NOT NULL,\n  `assigned_count` int(11) NOT NULL DEFAULT 0,\n  `unassigned_count` int(11) NOT NULL DEFAULT 0,\n  `needs_room_count` int(11) NOT NULL DEFAULT 0,\n  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),\n  PRIMARY KEY (`id`),\n  KEY `idx_tqc_run_id` (`run_id`),\n  KEY `idx_tqc_selected` (`is_selected`,`created_at`),\n  KEY `idx_tqc_created_at` (`created_at`),\n  CONSTRAINT `fk_tqc_run_id` FOREIGN KEY (`run_id`) REFERENCES `timetable_quality_runs` (`run_id`) ON DELETE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci',
    "CREATE TABLE `attendance` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `student_id` int(11) NOT NULL,\n  `timetable_id` int(11) NOT NULL,\n  `attendance_date` date NOT NULL,\n  `status` enum('Present','Absent','Late') NOT NULL DEFAULT 'Absent',\n  `marked_by` int(11) NOT NULL COMMENT 'Faculty ID who marked the attendance',\n  `marked_at` timestamp NULL DEFAULT current_timestamp(),\n  `remarks` varchar(255) DEFAULT NULL,\n  `created_at` timestamp NULL DEFAULT current_timestamp(),\n  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `unique_attendance` (`student_id`,`timetable_id`,`attendance_date`),\n  KEY `idx_student_date` (`student_id`,`attendance_date`),\n  KEY `idx_timetable_date` (`timetable_id`,`attendance_date`),\n  KEY `idx_marked_by` (`marked_by`),\n  KEY `idx_attendance_date` (`attendance_date`),\n  KEY `idx_attendance_status` (`status`),\n  CONSTRAINT `attendance_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE,\n  CONSTRAINT `attendance_ibfk_2` FOREIGN KEY (`timetable_id`) REFERENCES `timetable` (`id`) ON DELETE CASCADE,\n  CONSTRAINT `attendance_ibfk_3` FOREIGN KEY (`marked_by`) REFERENCES `faculty` (`id`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
    "CREATE TABLE `attendance_logs` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `event_uuid` varchar(64) NOT NULL,\n  `device_id` varchar(128) NOT NULL,\n  `student_id` int(11) NOT NULL,\n  `timetable_id` int(11) NOT NULL,\n  `attendance_date` date NOT NULL,\n  `status` enum('Present','Absent','Late') NOT NULL,\n  `marked_by_user_id` int(11) NOT NULL,\n  `marked_by_faculty_id` int(11) NOT NULL,\n  `captured_at` datetime DEFAULT NULL,\n  `confidence` decimal(5,4) DEFAULT NULL,\n  `face_model` varchar(120) DEFAULT NULL,\n  `detector_model` varchar(120) DEFAULT NULL,\n  `remarks` varchar(255) DEFAULT NULL,\n  `processing_status` enum('pending','processed','failed') NOT NULL DEFAULT 'pending',\n  `error_message` varchar(500) DEFAULT NULL,\n  `raw_payload` longtext DEFAULT NULL,\n  `created_at` timestamp NULL DEFAULT current_timestamp(),\n  `processed_at` timestamp NULL DEFAULT NULL,\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `uk_attendance_logs_event_uuid` (`event_uuid`),\n  KEY `idx_attendance_logs_processing_status` (`processing_status`),\n  KEY `idx_attendance_logs_created_at` (`created_at`),\n  KEY `idx_attendance_logs_student_timetable_date` (`student_id`,`timetable_id`,`attendance_date`),\n  KEY `fk_attendance_logs_timetable` (`timetable_id`),\n  KEY `fk_attendance_logs_marked_by_faculty` (`marked_by_faculty_id`),\n  KEY `fk_attendance_logs_marked_by_user` (`marked_by_user_id`),\n  CONSTRAINT `fk_attendance_logs_marked_by_faculty` FOREIGN KEY (`marked_by_faculty_id`) REFERENCES `faculty` (`id`),\n  CONSTRAINT `fk_attendance_logs_marked_by_user` FOREIGN KEY (`marked_by_user_id`) REFERENCES `users` (`id`),\n  CONSTRAINT `fk_attendance_logs_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`),\n  CONSTRAINT `fk_attendance_logs_timetable` FOREIGN KEY (`timetable_id`) REFERENCES `timetable` (`id`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
    "CREATE TABLE `proxy_log` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `original_faculty_id` int(11) NOT NULL,\n  `proxy_faculty_id` int(11) DEFAULT NULL,\n  `timetable_id` int(11) NOT NULL,\n  `absence_date` date NOT NULL,\n  `status` enum('ASSIGNED','UNASSIGNED') NOT NULL,\n  `approval_status` enum('PENDING','APPROVED','REJECTED') DEFAULT 'PENDING',\n  `approval_date` datetime DEFAULT NULL,\n  `approved_by` int(11) DEFAULT NULL,\n  `approval_notes` text DEFAULT NULL,\n  PRIMARY KEY (`id`),\n  KEY `timetable_id` (`timetable_id`),\n  KEY `fk_proxy_log_approved_by` (`approved_by`),\n  KEY `idx_proxy_log_approval_status` (`approval_status`),\n  KEY `idx_proxy_log_approval_date` (`approval_date`),\n  KEY `fk_proxy_log_original_faculty_id` (`original_faculty_id`),\n  KEY `fk_proxy_log_proxy_faculty_id` (`proxy_faculty_id`),\n  CONSTRAINT `fk_proxy_log_approved_by` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,\n  CONSTRAINT `fk_proxy_log_original_faculty_id` FOREIGN KEY (`original_faculty_id`) REFERENCES `faculty` (`user_id`) ON DELETE CASCADE,\n  CONSTRAINT `fk_proxy_log_proxy_faculty_id` FOREIGN KEY (`proxy_faculty_id`) REFERENCES `faculty` (`user_id`) ON DELETE SET NULL,\n  CONSTRAINT `proxy_log_ibfk_3` FOREIGN KEY (`timetable_id`) REFERENCES `timetable` (`id`) ON DELETE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
    "CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `attendance_summary` AS select `s`.`id` AS `student_id`,`s`.`name` AS `student_name`,`s`.`roll_number` AS `roll_number`,`subj`.`id` AS `subject_id`,`subj`.`name` AS `subject_name`,`c`.`id` AS `class_id`,`c`.`name` AS `class_name`,`d`.`id` AS `division_id`,`d`.`name` AS `division_name`,count(distinct `t`.`id`) AS `total_lectures_scheduled`,count(distinct case when `a`.`status` = 'Present' then `a`.`id` end) AS `lectures_attended`,count(distinct case when `a`.`status` = 'Late' then `a`.`id` end) AS `lectures_late`,count(distinct case when `a`.`status` = 'Absent' then `a`.`id` end) AS `lectures_missed`,round(count(distinct case when `a`.`status` in ('Present','Late') then `a`.`id` end) * 100.0 / nullif(count(distinct `t`.`id`),0),2) AS `attendance_percentage` from (((((`students` `s` join `timetable` `t`) left join `attendance` `a` on(`a`.`student_id` = `s`.`id` and `a`.`timetable_id` = `t`.`id`)) left join `subjects` `subj` on(`t`.`subject_id` = `subj`.`id`)) left join `classes` `c` on(`t`.`class_id` = `c`.`id`)) left join `divisions` `d` on(`t`.`division_id` = `d`.`id`)) where `t`.`course_id` = `s`.`course_id` and `t`.`class_id` = `s`.`class_id` and `t`.`division_id` = `s`.`division_id` group by `s`.`id`,`subj`.`id`,`c`.`id`,`d`.`id`",
    "CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `student_overall_attendance` AS select `s`.`id` AS `student_id`,`s`.`name` AS `student_name`,`s`.`roll_number` AS `roll_number`,`s`.`email` AS `email`,`c`.`name` AS `class_name`,`d`.`name` AS `division_name`,count(distinct case when `a`.`attendance_date` <= curdate() then `t`.`id` end) AS `total_lectures`,count(distinct case when `a`.`status` = 'Present' then `a`.`id` end) AS `total_present`,count(distinct case when `a`.`status` = 'Late' then `a`.`id` end) AS `total_late`,count(distinct case when `a`.`status` = 'Absent' then `a`.`id` end) AS `total_absent`,round(count(distinct case when `a`.`status` in ('Present','Late') then `a`.`id` end) * 100.0 / nullif(count(distinct case when `a`.`attendance_date` <= curdate() then `t`.`id` end),0),2) AS `overall_percentage` from ((((`students` `s` join `classes` `c` on(`s`.`class_id` = `c`.`id`)) join `divisions` `d` on(`s`.`division_id` = `d`.`id`)) left join `timetable` `t` on(`t`.`course_id` = `s`.`course_id` and `t`.`class_id` = `s`.`class_id` and `t`.`division_id` = `s`.`division_id`)) left join `attendance` `a` on(`a`.`student_id` = `s`.`id` and `a`.`timetable_id` = `t`.`id`)) group by `s`.`id`,`c`.`id`,`d`.`id`",
    "CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_consecutive_slot_opportunities` AS select `c`.`code` AS `course_code`,`c`.`name` AS `course_name`,`cl`.`name` AS `class_name`,`d`.`name` AS `division_name`,`days`.`day_name` AS `day_name`,cast('09:00:00' as time(6)) AS `slot_start`,cast('17:00:00' as time(6)) AS `slot_end`,timestampdiff(HOUR,cast('09:00:00' as time(6)),cast('17:00:00' as time(6))) AS `available_hours`,coalesce(`scheduled`.`occupied_hours`,0) AS `occupied_hours`,timestampdiff(HOUR,cast('09:00:00' as time(6)),cast('17:00:00' as time(6))) - coalesce(`scheduled`.`occupied_hours`,0) AS `free_hours`,floor((timestampdiff(HOUR,cast('09:00:00' as time(6)),cast('17:00:00' as time(6))) - coalesce(`scheduled`.`occupied_hours`,0)) / (`c`.`lecture_duration_minutes` / 60.0)) AS `max_consecutive_sessions` from ((((`courses` `c` join `classes` `cl`) join `divisions` `d`) join (select 'Monday' AS `day_name` union select 'Tuesday' AS `Tuesday` union select 'Wednesday' AS `Wednesday` union select 'Thursday' AS `Thursday` union select 'Friday' AS `Friday` union select 'Saturday' AS `Saturday`) `days`) left join (select `timetable`.`course_id` AS `course_id`,`timetable`.`class_id` AS `class_id`,`timetable`.`division_id` AS `division_id`,`timetable`.`day_of_week` AS `day_of_week`,sum(timestampdiff(HOUR,`timetable`.`start_time`,`timetable`.`end_time`)) AS `occupied_hours` from `timetable` group by `timetable`.`course_id`,`timetable`.`class_id`,`timetable`.`division_id`,`timetable`.`day_of_week`) `scheduled` on(`scheduled`.`course_id` = `c`.`id` and `scheduled`.`class_id` = `cl`.`id` and `scheduled`.`division_id` = `d`.`id` and `scheduled`.`day_of_week` = `days`.`day_name`)) where `c`.`id` = 3 and `cl`.`id` = 1 and `d`.`id` = 1",
    "CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_curriculum_overview` AS select `c`.`id` AS `course_id`,`c`.`name` AS `course_name`,`c`.`program` AS `program`,`c`.`duration_years` AS `duration_years`,`c`.`total_semesters` AS `total_semesters`,`sem`.`semester_number` AS `semester_number`,`sem`.`semester_name` AS `semester_name`,count(`s`.`id`) AS `total_subjects`,sum(`s`.`credits`) AS `total_credits`,sum(case when `s`.`course_type` = 'Core' then `s`.`credits` else 0 end) AS `core_credits`,sum(case when `s`.`course_type` like '%Elective%' then `s`.`credits` else 0 end) AS `elective_credits`,sum(case when `s`.`theory_practical` = 'Practical' then `s`.`credits` else 0 end) AS `practical_credits` from ((`courses` `c` join `semesters` `sem`) left join `subjects` `s` on(`c`.`id` = `s`.`course_id` and `sem`.`id` = `s`.`semester_id`)) where `c`.`is_active` = 1 group by `c`.`id`,`c`.`name`,`c`.`program`,`c`.`duration_years`,`c`.`total_semesters`,`sem`.`semester_number`,`sem`.`semester_name` order by `c`.`program`,`c`.`name`,`sem`.`semester_number`",
    "CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_faculty_daily_workload` AS select `t`.`faculty_id` AS `faculty_id`,`f`.`name` AS `faculty_name`,`t`.`day_of_week` AS `day_of_week`,count(0) AS `total_sessions`,sum(time_to_sec(timediff(`t`.`end_time`,`t`.`start_time`)) / 3600) AS `total_hours`,group_concat(distinct `c`.`code` order by `c`.`code` ASC separator ',') AS `courses_taught` from ((`timetable` `t` join `faculty` `f` on(`f`.`user_id` = `t`.`faculty_id`)) join `courses` `c` on(`c`.`id` = `t`.`course_id`)) group by `t`.`faculty_id`,`f`.`name`,`t`.`day_of_week`",
    "CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_faculty_schedule_conflicts` AS select `t1`.`faculty_id` AS `faculty_id`,`f`.`name` AS `faculty_name`,`t1`.`day_of_week` AS `day_of_week`,`t1`.`start_time` AS `start_time`,`t1`.`end_time` AS `end_time`,`t1`.`course_id` AS `course1_id`,`c1`.`code` AS `course1_code`,`c1`.`name` AS `course1_name`,`t1`.`class_id` AS `class1_id`,`t2`.`course_id` AS `course2_id`,`c2`.`code` AS `course2_code`,`c2`.`name` AS `course2_name`,`t2`.`class_id` AS `class2_id`,'Time Overlap' AS `conflict_reason` from ((((`timetable` `t1` join `timetable` `t2` on(`t1`.`faculty_id` = `t2`.`faculty_id` and `t1`.`day_of_week` = `t2`.`day_of_week` and `t1`.`id` < `t2`.`id` and `t1`.`start_time` < `t2`.`end_time` and `t1`.`end_time` > `t2`.`start_time`)) join `faculty` `f` on(`f`.`user_id` = `t1`.`faculty_id`)) join `courses` `c1` on(`c1`.`id` = `t1`.`course_id`)) join `courses` `c2` on(`c2`.`id` = `t2`.`course_id`))",
